values ('vsim-93oi1y', 'Vsim', 'Michelle', 'Michelle', 'your founders'' simulation work and the questions robotics teams ask before they trust a faster simulator', true, to_jsonb('1 long-form article + 2 short insights'::text), null, 'call', false, false)
